    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContract = address(c).balance;
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContract = address(c).balance;
        assert(afterUser >= beforeUser && afterUser - beforeUser == amount && afterContract >= beforeContract && afterContract - beforeContract == amount);
    }

    receive() external payable {}
}

